def maxWidthRamp(nums):
    cand = []
    for i, x in enumerate(nums):
        if not cand or x < nums[cand[-1]]:
            cand.append(i)
    best = 0
    for j in range(len(nums) - 1, -1, -1):
        while cand and nums[cand[-1]] <= nums[j]:
            best = max(best, j - cand.pop())
        if not cand:
            break
    return best
